<script setup>
import { onMounted, ref } from 'vue'
import { useRouter } from 'vue-router'
import { api } from '../api.js'
import { auth, notify } from '../state.js'
import '../components/portal-addons.css'
const router = useRouter(), email = ref(''), password = ref(''), role = ref('student'), loading = ref(false), error = ref('')
async function submit() { loading.value = true; error.value = ''; try { auth.user = (await api.login(email.value, password.value, role.value)).user; auth.checked = true; router.push('/dashboard') } catch (e) { error.value = e.message } finally { loading.value = false } }
</script>
<template><div class="auth-layout"><section class="auth-brand-side"><div class="brand brand-on-dark"><span class="brand-icon">E</span><span>Exam<span class="brand-light">wise</span><small>EXAMINATION MANAGEMENT</small></span></div><div class="auth-message"><div class="eyebrow">A clearer way to assess</div><h1>Every examination,<br>in its right place.</h1><p>One thoughtful workspace for scheduling, assessment and academic progress.</p><div class="auth-footnote">SECURE · SIMPLE · BUILT FOR ACADEMIA</div></div></section><section class="auth-form-side"><div class="auth-card"><div class="eyebrow">WELCOME BACK</div><h2>Sign in to your account</h2><p class="muted">Use your ExamWise email and password.</p><form @submit.prevent="submit"><label>Sign in as</label><select v-model="role" required class="auth-role-select"><option value="student">Student</option><option value="examiner">Examiner</option><option value="admin">Admin</option></select><label>Email address</label><input v-model="email" type="email" required autocomplete="username" placeholder="you@university.edu"><label>Password</label><input v-model="password" type="password" required autocomplete="current-password" placeholder="Enter your password"><div v-if="error" class="alert alert-danger py-2">{{ error }}</div><button class="btn btn-primary w-100 mt-3" :disabled="loading">{{ loading ? 'Signing in…' : 'Sign in' }} <span>→</span></button></form><div class="auth-switch">New to Examwise? <RouterLink to="/register">Create a student account</RouterLink></div><div class="security-note">Examiners are added by Admin. Only Students can self-register.</div></div></section></div></template>
